async function main() {
  let updated = 0;
  for (const p of P) {
    const existing = await prisma.prompt.findFirst({ where: { title: p.title, category: U } });
    if (!existing) { console.warn(`NOT FOUND: ${p.title}`); continue; }
    await prisma.prompt.update({ where: { id: existing.id }, data: { previewHtml: p.previewHtml } });
    updated++;
  }
  console.log(`Updated ${updated} prompts (add-previews batch 3).`);
}
main().catch(e=>{console.error(e);process.exit(1)}).finally(()=>prisma.$disconnect());
